	@Test
	void coveredSnapshotCommitPersistsWithoutMutationJournal(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = smallMapConfig();
		assertTrue(config.getAutoGrow(), "The covered write must use the normal auto-growing store policy");
		CountingLmdbStore store = new CountingLmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			store.probe.reset();
			try (RepositoryConnection writer = repository.getConnection();
					RepositoryConnection observer = repository.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				writer.add(SUBJECT, PREDICATE, OBJECT);
				writer.setNamespace("m3", "urn:m3:");
				writer.commit();

				assertTrue(observer.hasStatement(SUBJECT, PREDICATE, OBJECT, false),
						"A separate connection must see the committed statement immediately");
				assertEquals("urn:m3:", observer.getNamespace("m3"),
						"The committed namespace must be visible immediately");
			}
		} finally {
			repository.shutDown();
		}

		SailRepository reopened = new SailRepository(new LmdbStore(directory.toFile(), config));
		try {
			reopened.init();
			try (RepositoryConnection connection = reopened.getConnection()) {
				assertTrue(connection.hasStatement(SUBJECT, PREDICATE, OBJECT, false),
						"The committed statement must survive reopening the LMDB store");
				assertEquals("urn:m3:", connection.getNamespace("m3"),
						"The committed namespace must survive reopening the LMDB store");
			}
		} finally {
			reopened.shutDown();
		}

		assertEquals(0, store.probe.journalAllocations.get(),
				"The covered snapshot commit must not allocate a whole-transaction mutation journal");
	}

